// Captures the chat message AND classifies it. Writes the JSON to
// /data/chatin and hands a routing decision to the next node.
// Path B v2 — sovereign loop, native only, no MCP.

const fs = require('fs');
const path = require('path');

const CHATIN_DIR = '/data/chatin';
fs.mkdirSync(CHATIN_DIR, { recursive: true });

const input = $input.first().json || {};
const payload = input.body && typeof input.body === 'object' ? input.body : input;
const headers = $input.first().headers || input.headers || {};

function pick(obj, keys) {
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return null;
}

const senderRaw = pick(payload, ['user_name', 'username', 'userName', 'name']) || 'unknown';
const userId    = pick(payload, ['user_id', 'userId']);
const channel   = pick(payload, ['channel_name', 'channelName', 'channel']) || 'unknown-channel';
const channelId = pick(payload, ['channel_id', 'channelId']);
const postId    = pick(payload, ['post_id', 'postId', 'message_id']);
const rawText   = pick(payload, ['text', 'message', 'content']) || '';
const trigger   = pick(payload, ['trigger_word', 'triggerWord']);
const ts        = pick(payload, ['timestamp', 'created_at']);

// Strip the trigger word from the head of the text if it's there.
const cleanedText = String(rawText)
  .replace(/^@?(nas|chat-bot|nas-bot)\s*/i, '')
  .trim();

// Intent classifier (keyword-based — fast, deterministic, no LLM needed for
// the first pass). The Ollama-based deeper classifier can be layered later.
const lower = cleanedText.toLowerCase();
const CHANGE_KEYS = ['change', 'update', 'fix', 'add', 'remove', 'rename', 'replace', 'set', 'edit', 'tweak', 'shift', 'make'];
const APP_TARGETS = ['tab', 'button', 'page', 'view', 'modal', 'header', 'footer', 'card', 'label', 'text', 'color', 'icon', 'route', 'screen'];
const hasChangeVerb = CHANGE_KEYS.some(w => lower.includes(w));
const hasAppTarget = APP_TARGETS.some(w => lower.includes(w));

let intent = 'note';
if (hasChangeVerb && hasAppTarget) intent = 'app-change-request';
else if (hasChangeVerb) intent = 'change-request';
else if (lower.includes('?')) intent = 'question';
else if (lower.match(/^test\b|test from|capture|verify/)) intent = 'test';

const record = {
  captured_at: new Date().toISOString(),
  source: 'synology-chat-outgoing-webhook',
  intent,
  normalized: {
    sender: senderRaw,
    user_id: userId,
    channel,
    channel_id: channelId,
    post_id: postId,
    trigger_word: trigger,
    text: cleanedText,
    raw_text: rawText,
    chat_timestamp: ts
  },
  headers,
  payload
};

const safeTs = record.captured_at.replace(/[:.]/g, '-');
const sender = String(senderRaw).replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 32);
const postIdFragment = (postId || '').toString().slice(0, 8);
const filename = path.join(
  CHATIN_DIR,
  `${safeTs}__${sender}${postIdFragment ? '__' + postIdFragment : ''}.json`
);

fs.writeFileSync(filename, JSON.stringify(record, null, 2));

// Compose the ack text the next node will post back.
let ack;
switch (intent) {
  case 'app-change-request':
    ack = `🔧 *App change logged.* I heard: "${cleanedText.slice(0, 220)}". Dispatch will pick it up and open a PR — you'll see the deploy land here when it's live.`;
    break;
  case 'change-request':
    ack = `📝 *Request logged.* I heard: "${cleanedText.slice(0, 220)}". Will route to Dispatch.`;
    break;
  case 'question':
    ack = `❓ *Question received.* I'll think and reply: "${cleanedText.slice(0, 220)}"`;
    break;
  case 'test':
    ack = `✅ *Capture confirmed.* "${cleanedText.slice(0, 220)}" — written to /volume1/PoeTech/ChatIn.`;
    break;
  default:
    ack = `📥 *Captured.* "${cleanedText.slice(0, 220)}"`;
}

return [{
  json: {
    written: filename,
    intent,
    sender,
    channel,
    text: cleanedText,
    ack_text: ack
  }
}];
